css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .58); position: relative; overflow: hidden; }
.loader .cloth { position: absolute; left: 2%; right: 2%; bottom: 8%; height: 34%; border-radius: 5px; background: repeating-linear-gradient(90deg, color-mix(in srgb, var(--accent-2) 92%, var(--accent)) 0 6%, var(--accent-2) 0 12%); }
.loader .crease { position: absolute; left: 4%; bottom: 20%; height: 8%; width: 0; border-radius: 3px; background: color-mix(in srgb, var(--accent) 55%, transparent); animation: iron-smooth calc(var(--loader-speed) * 2.6) ease-in-out infinite; }
.loader .iron { position: absolute; left: 4%; bottom: 30%; width: 30%; height: 30%; border-radius: 6px 6px 46% 12%; background: linear-gradient(color-mix(in srgb, #fff 20%, var(--accent)), var(--accent)); animation: iron-glide calc(var(--loader-speed) * 2.6) ease-in-out infinite; }
.loader .iron::after { content: ''; position: absolute; left: 18%; right: 18%; bottom: 96%; height: 46%; border-radius: 999px 999px 0 0; box-shadow: inset 0 4px 0 var(--accent); }
.loader i { position: absolute; bottom: 62%; width: 9%; height: 9%; border-radius: 50%; background: color-mix(in srgb, var(--accent-2) 75%, transparent); opacity: 0; animation: iron-steam calc(var(--loader-speed) * 1.3) ease-out infinite, iron-glide calc(var(--loader-speed) * 2.6) ease-in-out infinite; }
.loader i:nth-of-type(1) { left: 10%; }
.loader i:nth-of-type(2) { left: 18%; animation-delay: calc(var(--loader-speed) * .43), 0s; }
.loader i:nth-of-type(3) { left: 26%; animation-delay: calc(var(--loader-speed) * .86), 0s; }
@keyframes iron-glide { 0%, 100% { transform: translateX(0); } 50% { transform: translateX(calc(var(--loader-size) * .58)); } }
@keyframes iron-smooth { 0% { width: 0; opacity: 1; } 50% { width: 62%; opacity: 1; } 92%, 100% { width: 62%; opacity: 0; } }
@keyframes iron-steam { 0% { opacity: 0; } 20% { opacity: .85; } 100% { opacity: 0; } }
